use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let intervals: Vec<(i64, i64)> = input
        .as_array()
        .unwrap()
        .iter()
        .map(|v| (v[0].as_i64().unwrap(), v[1].as_i64().unwrap()))
        .collect();

    let mut start = intervals[0].0;
    let mut end = intervals[0].1;

    for interval in &intervals[1..] {
        if interval.0 < start {
            start = interval.0;
        }
        if interval.1 > end {
            end = interval.1;
        }
    }

    Value::from(end - start)
}
